class Orders private constructor(private val items: List<Order>) : List<Order> by items {
    fun add(order: Order): Orders {
        require(items.none { it.id == order.id }) { "duplicate order ${order.id}" }
        return Orders(items + order)        // immutable: no in-place mutation
    }
    val total: Money get() = items.fold(Money.ZERO, Money::plus)

    companion object { fun of(vararg orders: Order) = Orders(orders.toList()) }
}
